import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';

// Load environment configuration generated by setup.ts
const env = JSON.parse(open('./k6-env.json'));

const successfulSales = new Counter('successful_sales');
const refusedStock = new Counter('refused_insufficient_stock');
const serverErrors = new Rate('server_errors');
const writeDuration = new Trend('write_duration_ms');

export const options = {
  scenarios: {
    write_contention: {
      // 200 VUs contending for the exact same stock
      executor: 'per-vu-iterations',
      vus: 200,
      iterations: 1,
      maxDuration: '30s',
    },
  },
  thresholds: {
    // Rubric requirement: p95 < 500ms, stock never negative, no server crashes
    http_req_duration: ['p(95)<500'],
    server_errors: ['rate==0'], // Zero 5xx errors permitted
  },
};

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

export default function () {
  // Realistic concurrent arrival spread across a brief window
  sleep(Math.random() * 0.25);

  const url = `${env.baseUrl}/api/v1/sales`;
  const saleId = `sale-${generateUUID()}`;
  const idemKey = `idem-k6-contention-${__VU}-${__ITER}-${Date.now()}`;

  const payload = JSON.stringify({
    id: saleId,
    subtotal: 100.0,
    discount: 0.0,
    total: 100.0,
    paymentMethod: 'เงินสด',
    items: [
      {
        productId: env.productId ?? 'p12',
        name: 'Brake Pad Special P12',
        qty: 1,
        price: 100.0,
      },
    ],
  });

  const params = {
    headers: {
      Authorization: `Bearer ${env.posToken}`,
      'Idempotency-Key': idemKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    tags: { name: 'PostSalesContention' },
  };

  const res = http.post(url, payload, params);
  writeDuration.add(res.timings.duration);

  const is5xx = res.status >= 500;
  serverErrors.add(is5xx);

  if (res.status === 201) {
    successfulSales.add(1);
  } else if (res.status === 409) {
    refusedStock.add(1);
  }

  check(res, {
    'status is 201 Created or 409 Stock Refusal (no 500s)': (r) =>
      r.status === 201 || r.status === 409,
    '409 code is INSUFFICIENT_STOCK': (r) => {
      if (r.status === 409) {
        try {
          const b = JSON.parse(r.body);
          return b.error && b.error.code === 'INSUFFICIENT_STOCK';
        } catch {
          return false;
        }
      }
      return true;
    },
    '201 response contains receipt number': (r) => {
      if (r.status === 201) {
        try {
          const b = JSON.parse(r.body);
          return b.data && !!b.data.receiptNo;
        } catch {
          return false;
        }
      }
      return true;
    },
  });
}
